import (
	"encoding/json"
	"net/http/httptest"
	"sort"
	"strings"
	"testing"
)

// Not every assertion template uses every import; Go treats an unused import as
// a compile error, and a test that fails to build would otherwise be
// indistinguishable from a claim that could not be confirmed.
var (
	_ = strings.NewReader
	_ = json.Unmarshal
	_ = sort.Strings
	_ = strings.TrimSpace
	_ = toNumber
)

func keys(m map[string]any) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

func headerNames(h map[string][]string) []string {
	out := make([]string, 0, len(h))
	for k := range h {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// firstObject unwraps a top-level array so a list endpoint is judged by the
// shape of its elements, which is what the spec describes.
func firstObject(v any) map[string]any {
	switch t := v.(type) {
	case map[string]any:
		return t
	case []any:
		if len(t) > 0 {
			if obj, ok := t[0].(map[string]any); ok {
				return obj
			}
		}
	}
	return nil
}

func toNumber(v any) float64 {
	if f, ok := v.(float64); ok {
		return f
	}
	return -1
}

func jsonType(v any) string {
	switch v.(type) {
	case string:
		return "string"
	case bool:
		return "boolean"
	case float64:
		return "number"
	case []any:
		return "array"
	case map[string]any:
		return "object"
	}
	return "null"
}

func TestContractVerify(t *testing.T) {
	req := httptest.NewRequest("POST", "/payouts", strings.NewReader("{\"accountNumber\": \"test-accountnumber\", \"bankCode\": \"test-bankcode\", \"amount\": \"1000\", \"currency\": \"NGN\", \"narration\": \"test-narration\", \"reference\": \"test-reference\"}"))
	req.Header.Set("Idempotency-Key", "test-idempotency-key")
	req.Header.Set("X-Api-Key", "test-key")
	req.SetPathValue("id", "test-id")
	rec := httptest.NewRecorder()
	CreatePayout(rec, req)

	var payload any
	if err := json.Unmarshal(rec.Body.Bytes(), &payload); err != nil {
		t.Fatalf("response is not JSON: %v", err)
	}
	obj := firstObject(payload)
	if obj == nil {
		t.Fatalf("response is not a JSON object: %s", rec.Body.String())
	}
	if _, ok := obj["fee"]; !ok {
		t.Fatalf("spec documents field %q; response carries keys %v", "fee", keys(obj))
	}
}

